import{_ as l,l as o,o as e,c as i,v as t,p as s,x as n,d as p,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"应计与现金流","description":"","frontmatter":{"title":"应计与现金流","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/accrual-vs-cash.md","filePath":"quant/accrual-vs-cash.md","lastUpdated":1789023840000}'),d={name:"quant/accrual-vs-cash.md"};function E(u,a,A,m,_,B){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="应计与现金流" tabindex="-1">应计与现金流 <a class="header-anchor" href="#应计与现金流" aria-label="Permalink to &quot;应计与现金流&quot;">​</a></h1><div class="epigraph"><p>应计把经济事项的确认时点与现金收付时点拆开；把净利润里的应计分量单独排序，后续回报往往更低。</p><footer>—— 据 Sloan, The Accounting Review, 1996；Penman, Financial Statement Analysis 第 8 章整理</footer></div><p>上一课<a href="/quant/three-statements-link">三张表怎么连</a>钉死了两条勾稽链。身份闭合之后，利润与现金仍经常不同步。本课只补这一块差：应计是什么、怎样从已有字段拆出来、它对后面质量因子意味着什么。不重推勾稽，也不把可用日期提前讲完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只用净利润排序，你把尚未收到的收入、尚未付出的费用、以及营运资本占用，都算进「盈利」。Sloan 把盈余拆成应计与现金两个分量，发现应计高的公司随后平均回报更低。缺口因此不是再读一张利润表，而是承认：<strong>同一条勾稽链上，NI 与 OCF 的差本身就是可交易对象</strong>。</p><p>Beaver 更早就指出年度盈余公告有信息含量；Sloan 的贡献是把信息拆开，指出市场对现金分量的定价更接近后续实现，对应计分量则系统性偏乐观。后课盈利质量、应计异象都从这次拆分起步。</p><h3 id="应计不是造假的别名" tabindex="-1">应计不是造假的别名 <a class="header-anchor" href="#应计不是造假的别名" aria-label="Permalink to &quot;应计不是造假的别名&quot;">​</a></h3><p>匹配原则要求收入与费用在经济事项发生时确认，于是折旧、坏账准备、收入确认时点都进入应计。高应计可以是增长期的营运资本占用，也可以是激进确认。本课先把它当成<strong>计量差</strong>，取证式的盈余管理留给<a href="/quant/earnings-quality">盈利质量</a>。把应计一律读成欺诈，后面的因子会把正常扩张的公司全部做空。</p><p><span class="marginnote">资产负债表法用营运资本与折旧等变动估计应计；现金流量表法直接用 \\(NI-OCF\\)。两种口径在并购、一次性项目上会分叉，回测必须锁死一种。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>简化定义：\\(Accruals \\approx NI - OCF\\)。更细的资产负债表法把非现金营运资本变动加上折旧摊销等。缩放通常用期初总资产，以便截面排序；这是 Sloan 的惯例，不是唯一合法分母。后课 Fama–French 风格的质量或盈利因子，会再决定要不要行业中性化——那是组合步骤，不改变应计定义。</p><p>现金分量 \\(OCF\\) 来自上一课链二。应计分量是链一与链二的差。因此本课在勾稽之后才有意义：若 NI 与 OCF 字段对不上同一报告期，差就没有经济内容。</p>',12)),(e(),s(h,null,{default:n(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ECON%5B%22%E7%BB%8F%E6%B5%8E%E4%BA%8B%E9%A1%B9%22%5D%20--%3E%20ACC%5B%22%E5%BA%94%E8%AE%A1%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20ACC%20--%3E%20NI%5B%22%E5%87%80%E5%88%A9%E6%B6%A6%22%5D%0A%20%20ECON%20--%3E%20CASH%5B%22%E7%8E%B0%E9%87%91%E6%94%B6%E4%BB%98%22%5D%0A%20%20CASH%20--%3E%20OCF%5B%22%E7%BB%8F%E8%90%A5%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20NI%20--%3E%20SPLIT%5B%22%E5%BA%94%E8%AE%A1%E5%88%86%E9%87%8F%22%5D%0A%20%20OCF%20--%3E%20SPLIT%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>质量管道常做多低应计、做空高应计，或把应计当作多因子模型里的控制。机制有两层。一层是会计：应计倾向于反转，激进确认的利润随后要用现金或转回补回来。一层是定价：若投资者按盈余总量形成预期，对应计分量的预期误差会在后续窗口释放。本课不估计 PEAD，只要求因子计算固定口径、固定缩放、固定是否用经营现金流还是自由现金流。</p><p><span class="marginnote">后课 PIT 会问：你用的 NI 与 OCF 是公告当时的版本，还是多年后重述的终局版。应计定义对了、时间戳错了，Sloan 的差仍会泄漏未来信息。</span></p><p>回测最低实现：同一 PIT 切片上取 NI 与 OCF，期间对齐、缩放用期初总资产，截面分位前截尾。并购年、会计变更年单独标记，不要让一次购买法把应计因子的空头塞满收购方。现金流法与资产负债表法若并行，只能当稳健性，不能一年用这个一年用那个还称为同一信号。Sloan 的结果对口径敏感，敏感本身说明应计是计量对象，不是一个不变的异象常数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不映射 XBRL 标签，不做审计取证。极端应计常与并购、会计政策变更、一次性项目缠在一起，需等<a href="/quant/earnings-quality">盈利质量</a>与<a href="/quant/goodwill-impairment">商誉与减值</a>。本课也不引入可用日期；下一课才把「当时能看到的数字」写成约束。价值因子的账面权益仍用上一课的存量，不应用应计去改写账面。</p><p>后课默认：应计与现金已拆开；讨论盈利时先问分量，再问总量。</p><p>应计与现金拆开之后，后课默认不再用「净利润排序」冒充质量。极端值处理（截尾、行业内 z）属于组合步骤，要写在来源卡上，以免把 Sloan 的经济内容做成样本修剪的产物。一次性项目与并购年已标记的，质量课会再降权，本课不必提前删掉这些观测造成幸存者。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>勾稽闭合后，NI 与 OCF 的差就是应计窗口。</li><li>应计是匹配原则的产物，不等于造假。</li><li>Sloan：高应计随后平均回报偏低，是质量因子的经典动机。</li><li>口径、缩放必须锁死，否则回测不可比。</li><li>时间戳尚未引入；下一课才讲 PIT。</li><li>出处：Sloan, <em>The Accounting Review</em>, 1996；Penman 第 8 章。</li></ul>',10))])}const q=l(d,[["render",E]]);export{f as __pageData,q as default};
